const $ = id => document.getElementById(id);
let lang = "cs", step = 0, verified = false;

function setLanguage(nextLang){
  lang = nextLang; document.documentElement.lang = lang;
  $("languageShortcut").innerHTML = `<span aria-hidden="true">${lang==="cs"?"🇨🇿":"🇬🇧"}</span> ${lang.toUpperCase()} <span class="language-chevron" aria-hidden="true">▾</span>`;
  document.querySelectorAll("[data-i18n]").forEach(node => { const value = copy[lang][node.dataset.i18n]; if(value) node.innerHTML = value; });
  $("quizTitle").textContent = copy[lang].quizTitle; $("quizCount").textContent = copy[lang].quizCount;
  document.querySelectorAll("[data-lang]").forEach(button=>{const selected=button.dataset.lang===lang;button.classList.toggle("language-card-selected",selected);button.setAttribute("aria-pressed",String(selected));const note=button.querySelector("small");if(note)note.textContent=selected?(lang==="cs"?"Vybráno":"Selected"):(button.dataset.lang==="cs"?"Vybrat":"Select");});
}

function startCourse(nextLang){
  setLanguage(nextLang); $("languageScreen").classList.add("hidden"); $("registration").classList.add("hidden"); $("success").classList.add("hidden"); $("course").classList.remove("hidden"); step=0; renderLesson(); window.scrollTo({top:0,behavior:"smooth"});
}

function renderLesson(){
  verified=false; const lesson=lessons[lang][step], total=lessons[lang].length;
  $("lessonIndex").textContent=String(step+1).padStart(2,"0"); $("lessonEyebrow").textContent=lesson.eyebrow; $("lessonTitle").textContent=lesson.title; $("lessonIntro").textContent=lesson.intro;
  const videoPanel=$("videoPanel");
  videoPanel.parentElement.classList.toggle("no-video-layout",step===5);
  if(step<5){
    const videoNumber=step+1;
    videoPanel.className="video-panel video-live";
    videoPanel.innerHTML=`<video controls playsinline preload="metadata" aria-label="${lang==="cs"?"Videonávod":"Video tutorial"}: ${lesson.title}"><source src="assets/videos/lesson-${videoNumber}.mp4" type="video/mp4"><track kind="subtitles" src="assets/videos/lesson-${videoNumber}.vtt" srclang="cs" label="České titulky" default>${lang==="cs"?"Váš prohlížeč nepodporuje přehrávání videa.":"Your browser does not support video playback."}</video><span class="video-time">${lesson.duration}</span>`;
  }else{
    videoPanel.className="video-panel hidden";
    videoPanel.innerHTML="";
  }
  const lessonPoints=$("lessonPoints");
  lessonPoints.className=step<=5?"lesson-points mode-points":"lesson-points";
  if(step===0){
    const cards=lesson.points.map(point=>`<li class="stacked-visual"><span class="point-image ${point.image}" aria-hidden="true"></span><span class="point-text">${point.text}</span></li>`);
    lessonPoints.innerHTML=`<li class="point-section-title"><h2>${lang==="cs"?"Režim sněžnice":"Snowshoe mode"}</h2></li>${cards.slice(0,3).join("")}<li class="point-section-title point-section-title-secondary"><h2>${lang==="cs"?"Režim mini-lyže":"Mini-ski mode"}</h2></li>${cards.slice(3).join("")}`;
  }else{
    lessonPoints.innerHTML=lesson.points.map(point=>`<li class="${step<=5?"stacked-visual":""} ${point.image?"":"text-only-point"}">${point.image?`<span class="point-image ${point.image}" aria-hidden="true"></span>`:""}<span class="point-text">${point.text}</span></li>`).join("");
  }
  $("quizCount").textContent=lang==="cs"?`${lesson.questions.length} ${lesson.questions.length===1?"otázka":lesson.questions.length<5?"otázky":"otázek"}`:`${lesson.questions.length} ${lesson.questions.length===1?"question":"questions"}`;
  $("quizQuestions").innerHTML=lesson.questions.map((item,i)=>`<fieldset class="quiz-item"><legend><span class="question-number">${i+1}.</span>${item.question}</legend>${item.answers.map((answer,j)=>`<label class="answer"><input type="radio" name="quiz-${i}" value="${j}"><span>${answer}</span></label>`).join("")}<p class="question-feedback" id="questionFeedback-${i}"></p></fieldset>`).join("");
  $("feedback").textContent=""; $("feedback").className="feedback"; $("backButton").textContent=step===0?(lang==="cs"?"Výběr jazyka":"Language selection"):copy[lang].back; $("backButton").disabled=false; $("continueButton").textContent=copy[lang].check;
  $("progressLabel").textContent=`${copy[lang].step} ${step+1} ${copy[lang].of} ${total}`; const percent=Math.round((step+1)/total*100); $("progressPercent").textContent=`${percent} %`; $("progressFill").style.width=`${percent}%`;
}

function handleContinue(){
  if(verified){ if(step<lessons[lang].length-1){step++;renderLesson();}else{$("course").classList.add("hidden");$("registration").classList.remove("hidden");} window.scrollTo({top:0,behavior:"smooth"}); return; }
  const questions=lessons[lang][step].questions; let complete=true, allCorrect=true;
  questions.forEach((item,i)=>{ const chosen=document.querySelector(`input[name="quiz-${i}"]:checked`), feedback=$(`questionFeedback-${i}`); feedback.className="question-feedback"; if(!chosen){complete=false;allCorrect=false;feedback.textContent=lang==="cs"?"Vyberte odpověď.":"Choose an answer.";}else if(Number(chosen.value)!==item.correct){allCorrect=false;feedback.textContent=item.hint;}else{feedback.textContent=lang==="cs"?"Správně.":"Correct.";feedback.classList.add("correct");} });
  if(!complete){showFeedback(lang==="cs"?`Odpovězte na všechny ${questions.length===4?"čtyři":"tři"} otázky.`:`Answer all ${questions.length} questions.`,false);return;} if(!allCorrect){showFeedback(lang==="cs"?"Některé odpovědi ještě opravte.":"Please correct the highlighted answers.",false);return;} verified=true;showFeedback(copy[lang].correct,true);$("continueButton").textContent=copy[lang].next;
}

function showFeedback(message,correct){$("feedback").textContent=message;$("feedback").className=`feedback ${correct?"correct":"error"}`;}
document.querySelectorAll("[data-lang]").forEach(button=>button.addEventListener("click",()=>setLanguage(button.dataset.lang)));
$("startButton").addEventListener("click",()=>startCourse(lang));
function closeLanguageMenu(){ $("languageMenu").classList.add("hidden"); $("languageShortcut").setAttribute("aria-expanded","false"); }
$("languageShortcut").addEventListener("click",event=>{event.stopPropagation();const opening=$("languageMenu").classList.contains("hidden");$("languageMenu").classList.toggle("hidden",!opening);$("languageShortcut").setAttribute("aria-expanded",String(opening));});
$("languageMenu").addEventListener("click",event=>event.stopPropagation());
document.querySelectorAll("[data-switch-lang]").forEach(button=>button.addEventListener("click",()=>{setLanguage(button.dataset.switchLang);closeLanguageMenu();if(!$("course").classList.contains("hidden"))renderLesson();}));
document.addEventListener("click",closeLanguageMenu);
document.addEventListener("keydown",event=>{if(event.key==="Escape")closeLanguageMenu();});
$("continueButton").addEventListener("click",handleContinue); $("backButton").addEventListener("click",()=>{if(step>0){step--;renderLesson();}else{$("course").classList.add("hidden");$("languageScreen").classList.remove("hidden");}window.scrollTo({top:0,behavior:"smooth"});});
document.querySelectorAll('input[name="warranty"]').forEach(radio=>radio.addEventListener("change",event=>{$("extendedConsents").classList.toggle("hidden",event.target.value!=="extended");$("formError").textContent="";}));
$("registrationForm").addEventListener("submit",event=>{event.preventDefault();const email=$("email").value.trim(),type=document.querySelector('input[name="warranty"]:checked')?.value;if(!/^\S+@\S+\.\S+$/.test(email)){$("formError").textContent=copy[lang].formEmail;return;}if(!type){$("formError").textContent=copy[lang].formChoice;return;}if(type==="extended"&&(!$('newsletterConsent').checked||!$('warrantyTerms').checked)){$("formError").textContent=copy[lang].formConsents;return;}$("registration").classList.add("hidden");$("success").classList.remove("hidden");$("successTitle").textContent=copy[lang].successTitle;$("successMessage").textContent=type==="extended"?copy[lang].extendedSuccess:copy[lang].standardSuccess;$("certificateType").textContent=type==="extended"?copy[lang].extendedCertificate:copy[lang].standardCertificate;$("certificateEmail").textContent=email;window.scrollTo({top:0,behavior:"smooth"});});
$("restartButton").addEventListener("click",()=>{$("registrationForm").reset();$("extendedConsents").classList.add("hidden");startCourse(lang);});
setLanguage("cs");
